<?php $kind=$event['kind'];$meta=$event['metadata'];$stats=$meta['details']??null;$presentation=App\Services\TicketDevelopment::presentation($event); ?>
<article class="git-time-item git-tone-<?= e($presentation['tone']) ?>" data-git-event-kind="<?= e($kind) ?>">
 <span class="git-time-node" aria-hidden="true"><?= icon($presentation['icon']) ?></span>
 <div class="git-event-card ticket-development-event<?= $kind==='pull_request'?' git-pr-event':'' ?>"><div class="git-event-content">
  <div class="git-time-heading"><span class="git-kind-pill"><?= icon($presentation['icon']) ?><?= e($presentation['label']) ?><?php if($kind==='pull_request'): ?><code>#<?= e(substr($event['external_key'],3)) ?></code><?php elseif($kind==='commit' && $event['commit_sha']): ?><code><?= e(substr($event['commit_sha'],0,12)) ?></code><?php endif; ?></span><span class="git-time-state"><?= e($event['state_label']) ?></span><?php if(($meta['date_known']??true)): ?><time datetime="<?= e(str_replace(' ','T',$event['occurred_at']).'Z') ?>" title="<?= e($event['occurred_at'].' UTC') ?>"><?= e(substr($event['occurred_at'],11,5)) ?> UTC</time><?php endif; ?></div>
  <div class="git-event-heading"><?php if($event['external_url']): ?><a href="<?= e($event['external_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($event['title']) ?> <?= icon('external') ?></a><?php else: ?><strong><?= e($event['title']) ?></strong><?php endif; ?></div>
  <div class="git-event-route"><?php if($meta['branch']??null): ?><span><?= icon('git-branch') ?><code><?= e($meta['branch']) ?></code></span><?php endif; ?><?php if(($meta['target_branch']??null) && !($meta['branch']??null)): ?><span>Branche source non fournie</span><?php endif; ?><?php if($meta['target_branch']??null): ?><span class="git-route-arrow" aria-label="vers">→</span><span class="git-target-branch"><code><?= e($meta['target_branch']) ?></code></span><?php endif; ?><?php if($kind==='pull_request' && ($meta['merge_sha']??null)): ?><span class="git-merge-sha"><?= icon('git-merge') ?>Commit de fusion <code><?= e(substr($meta['merge_sha'],0,12)) ?></code></span><?php elseif($kind!=='commit' && $event['commit_sha']): ?><span><?= icon('git-commit') ?><?= $kind==='pull_request'?'Commit source':'Commit' ?> <code><?= e(substr($event['commit_sha'],0,12)) ?></code></span><?php endif; ?></div>
  <div class="git-event-source"><span><?= e($event['provider']==='github'?'GitHub':'Bitbucket') ?> · <?= e($event['repository']) ?></span><?php if($meta['author']??null): ?><span>Auteur : <?= e($meta['author']) ?></span><?php endif; ?><?php if(!($meta['date_known']??true)): ?><span>Date non fournie par le fournisseur</span><?php endif; ?></div>
  <?php if($kind==='deployment'): ?><p class="git-environment">Environnement : <strong><?= e($meta['environment']??'Non fourni') ?></strong> · <?= $event['state']==='success'?'Déploiement confirmé par le fournisseur':'Déploiement non confirmé comme réussi' ?></p><?php elseif($kind==='pull_request' && $event['state']==='merged'): ?><p class="help-text git-merge-notice">Fusion du code · le déploiement est suivi séparément.</p><?php endif; ?>
  <?php if($kind==='pull_request'): $merge=App\Services\GitMonitor::conflict($event); ?><div class="git-merge-status"><?php if($merge['conflict']===true): ?><span class="merge-conflict-badge"><?= icon('alert') ?>Conflit de fusion</span><?php elseif($event['state']==='open'): ?><small><?= $merge['conflict']===false?'Aucun conflit signalé lors du dernier contrôle':'Conflits : vérification en attente ou indisponible' ?></small><?php endif; ?></div><div class="git-pr-summary">
   <?php if($stats): ?><button type="button" class="button subtle small-button" data-git-files="<?= (int)$event['id'] ?>"><?= (int)$stats['file_count'] ?> fichier(s) modifié(s)</button><span class="git-lines-added"><?= $stats['additions']===null?'Ajouts non fournis':'+'.(int)$stats['additions'] ?></span><span class="git-lines-deleted"><?= $stats['deletions']===null?'Suppressions non fournies':'−'.(int)$stats['deletions'] ?></span><small><?= (int)$stats['commit_count'] ?> commit(s)<?= $stats['commits_complete']?'':' · liste partielle' ?> · relevé du <?= e($stats['fetched_at']) ?><?php if($stats['revision']!==App\Services\GitPullRequest::revision($event)): ?> · à actualiser<?php endif; ?></small><?php else: ?><small>Commits et fichiers à récupérer.</small><?php endif; ?>
   <?php if($user['role']!=='viewer'): ?><button type="button" class="button subtle small-button" data-git-sync-pr="<?= (int)$event['id'] ?>"><?= $stats?'Actualiser les détails':'Récupérer les commits et fichiers' ?></button><?php endif; ?>
  </div><?php endif; ?>
 </div></div>
</article>
